3: // Simple tests to verify "placeholder" variant added in 2.13
4: public class PlaceholderSymbolTableTest extends com.fasterxml.jackson.core.BaseTest
5: {
6:     // Test to verify it is ok to try to find names, and that none
7:     // are ever found
8:     public void testBasicPlaceholderLookups() throws Exception
9:     {
10:         final ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(137);
11:         assertEquals(0, root.size());
12:         assertFalse(root.isCanonicalizing());
13: 
14:         ByteQuadsCanonicalizer placeholder = root.makeChildOrPlaceholder(0);
15: 
16:         assertEquals(-1, placeholder.size());
17:         assertFalse(placeholder.isCanonicalizing());
18: 
19:         final int[] quads = calcQuads("abcd1234efgh5678"); // 4 ints
20: 
21:         assertNull(placeholder.findName(quads[0]));
22:         assertNull(placeholder.findName(quads[0], quads[1]));
23:         assertNull(placeholder.findName(quads[0], quads[1], quads[2]));
24: 
25:         assertNull(placeholder.findName(quads, quads.length));
26:     }
27: 
28:     // Also: should not allow additions
29:     public void testBasicPlaceholderAddFails() throws Exception
30:     {
31:         final ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(137);
32:         ByteQuadsCanonicalizer placeholder = root.makeChildOrPlaceholder(0);
33: 
34:         final int[] quads = calcQuads("abcd1234efgh5678"); // 4 ints
35: 
36:         // try all variations
37:         try {
38:             placeholder.addName("abcd", placeholder.calcHash(quads[0]));
39:             fail("Should not pass");
40:         } catch (Exception e) {
41:             verifyException(e, "Cannot add names to Placeholder");
42:         }
43:         try {
44:             placeholder.addName("abcd1234",
45:                     placeholder.calcHash(quads[0], quads[1]));
46:             fail("Should not pass");
47:         } catch (Exception e) {
48:             verifyException(e, "Cannot add names to Placeholder");
49:         }
50:         try {
51:             placeholder.addName("abcd1234efgh",
52:                     placeholder.calcHash(quads[0], quads[1], quads[2]));
53:             fail("Should not pass");
54:         } catch (Exception e) {
55:             verifyException(e, "Cannot add names to Placeholder");
56:         }
57:         try {
58:             placeholder.addName("abcd1234efgh5678",
59:                     placeholder.calcHash(quads, quads.length));
60:             fail("Should not pass");
61:         } catch (Exception e) {
62:             verifyException(e, "Cannot add names to Placeholder");
63:         }
64: 
65: 
66:         // Verify nothing changed about state
67:         assertEquals(-1, placeholder.size());
